<script>
	import { onMount, onDestroy, tick } from 'svelte';
	import Icon from '$lib/utils/browser/icon.svelte';
	import veloraMark from '$lib/assets/velora-mark.svg';
	import { initialExperiences, refreshExperiences, experienceDetails, userHeadshot, compactNumber } from './catalog.js';
	import { parsePlace } from './network.js';

	let { network, user, state: connectionState, status, error, issues = [], onplay, onsignin } = $props();
	let games = $state(initialExperiences);
	let query = $state('');
	let view = $state('Home');
	let category = $state('All');
	let saved = $state([]);
	let recent = $state([]);
	let avatar = $state('');
	let accountOpen = $state(false);
	let sidebarOpen = $state(false);
	let selected = $state(null);
	let lookupError = $state('');
	let catalogError = $state(false);
	let resolving = $state(false);
	let customPlace = $state('');
	let customError = $state('');
	let detailDialog, openDialog, connectionDialog;
	let alive = true;
	const categories = ['All', 'Action', 'Roleplay', 'Survival', 'RPG', 'Simulation'];
	const filtered = $derived(games.filter(game => {
		const matches = `${game.name} ${game.creator} ${game.genre}`.toLowerCase().includes(query.trim().toLowerCase());
		const genre = category === 'All' || game.genre?.startsWith(category);
		const collection = view === 'Saved' ? saved.includes(game.placeId) : view === 'Continue' ? recent.some(item => item.placeId === game.placeId) : true;
		return matches && genre && collection;
	}));
	const recentGames = $derived(recent.map(item => games.find(game => game.placeId === item.placeId) || item));
	const title = $derived(query.trim() ? `Results for “${query.trim()}”` : view);

	onMount(() => {
		try {
			const bookmarks = JSON.parse(localStorage.getItem('velora.roblox.saved') || '[]');
			const history = JSON.parse(localStorage.getItem('velora.roblox.recent') || '[]');
			if (Array.isArray(bookmarks)) saved = bookmarks.filter(Number.isSafeInteger);
			if (Array.isArray(history)) recent = history.filter(item => Number.isSafeInteger(item?.placeId) && item.placeId > 0).slice(0, 8);
		} catch {}
	});
	onDestroy(() => { alive = false; });
	$effect(() => { const connection = network; if (connection) void loadCatalog(connection); });
	$effect(() => {
		const connection = network, account = user;
		avatar = '';
		if (connection && account) userHeadshot(connection, account.id).then(url => { if (alive) avatar = url; }).catch(() => {});
	});
	async function loadCatalog(connection) {
		try { const result = await refreshExperiences(connection); if (alive) { games = result; catalogError = false; } }
		catch { if (alive) catalogError = true; }
	}
	function navigate(next) { view = next; query = ''; category = 'All'; sidebarOpen = false; accountOpen = false; }
	function toggleSave(game) {
		saved = saved.includes(game.placeId) ? saved.filter(id => id !== game.placeId) : [...saved, game.placeId];
		try { localStorage.setItem('velora.roblox.saved', JSON.stringify(saved)); } catch {}
	}
	async function choose(game) {
		selected = game; lookupError = ''; resolving = false;
		await tick(); detailDialog.showModal();
	}
	async function openPlace(value) {
		const id = parsePlace(value);
		if (!id) { customError = 'Enter a Roblox game link or a numeric place ID.'; return; }
		customError = ''; openDialog.close(); query = '';
		const known = games.find(game => String(game.placeId) === id);
		if (known) { await choose(known); return; }
		await choose({ placeId: Number(id), name: 'Roblox experience', creator: '', genre: 'Experience', image: '' });
		if (!network) { lookupError = 'Waiting for your connection. You can try again in a moment.'; return; }
		resolving = true;
		try { const game = await experienceDetails(network, id); if (alive && selected?.placeId === Number(id)) { selected = game; games = [...games.filter(item => item.placeId !== game.placeId), game]; } }
		catch (error) { if (alive) lookupError = error.message; }
		finally { if (alive) resolving = false; }
	}
	function submitSearch(event) {
		event.preventDefault();
		if (parsePlace(query)) void openPlace(query);
		else { view = 'Discover'; category = 'All'; }
	}
	function launchSelected() {
		if (!selected) return;
		if (!user) { detailDialog.close(); onsignin(); return; }
		const game = selected;
		recent = [game, ...recent.filter(item => item.placeId !== game.placeId)].slice(0, 8);
		try { localStorage.setItem('velora.roblox.recent', JSON.stringify(recent)); } catch {}
		detailDialog.close(); onplay(game.placeId);
	}
</script>

{#snippet avatarImage(size = 'small')}
	<span class="avatar {size}">{#if avatar}<img src={avatar} crossorigin="anonymous" alt="" onerror={() => avatar = ''} />{:else}<svg viewBox="0 0 32 32" fill="currentColor" aria-hidden="true"><circle cx="16" cy="11" r="6"/><path d="M5 30v-5a11 11 0 0 1 22 0v5Z"/></svg>{/if}</span>
{/snippet}

{#snippet gameCard(game)}
	<article class="game-card">
		<button class="game-open" onclick={() => choose(game)} aria-label={`Open ${game.name}`}>
			<span class="game-art">{#if game.image}<img src={game.image} crossorigin={game.image.startsWith('https:') ? 'anonymous' : undefined} alt="" loading="lazy" />{:else}<span class="image-placeholder"><Icon name="games" size={48} /></span>{/if}<span class="hover-play"><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="m9 5 11 7-11 7Z"/></svg></span></span>
			<strong title={game.name}>{game.name}</strong>
			<span class="game-stats">{#if game.rating != null}<span><svg viewBox="0 0 20 20" fill="currentColor" aria-hidden="true"><path d="M7 8 10 2h2v5h5l-1 10H7ZM2 8h3v9H2Z"/></svg>{game.rating}%</span>{/if}{#if typeof game.playing === 'number'}<span><svg viewBox="0 0 20 20" fill="currentColor" aria-hidden="true"><circle cx="10" cy="5" r="3"/><path d="M4 18v-5a6 6 0 0 1 12 0v5Z"/></svg>{compactNumber(game.playing)}</span>{:else}<span>{game.genre}</span>{/if}</span>
		</button>
		<button class="save-game" class:saved={saved.includes(game.placeId)} aria-label={`${saved.includes(game.placeId) ? 'Unsave' : 'Save'} ${game.name}`} aria-pressed={saved.includes(game.placeId)} onclick={() => toggleSave(game)}><Icon name="bookmark" size={17} /></button>
	</article>
{/snippet}

<div class="roblox-home">
	<header class="topbar">
		<button class="icon-button menu-toggle" aria-label="Toggle navigation" onclick={() => sidebarOpen = !sidebarOpen}><span></span><span></span><span></span></button>
		<button class="wordmark" onclick={() => navigate('Home')} aria-label="Velora home"><img class="velora-mark" src={veloraMark} alt=""/><span>velora</span></button>
		<nav class="top-links" aria-label="Velora"><button onclick={() => navigate('Discover')}>Discover</button><a href="https://www.roblox.com/catalog" target="_blank" rel="noreferrer">Marketplace <span>↗</span></a><a href="https://create.roblox.com/" target="_blank" rel="noreferrer">Create <span>↗</span></a></nav>
		<form class="search" onsubmit={submitSearch}><Icon name="search" size={19} /><input aria-label="Search games or paste a Roblox link" placeholder="Search experiences" bind:value={query} />{#if query}<button type="button" class="icon-button" aria-label="Clear search" onclick={() => query = ''}><Icon name="close" size={16}/></button>{/if}</form>
		<div class="top-actions"><button class="icon-button open-game-button" aria-label="Open a game link or place ID" title="Open a game link" onclick={() => openDialog.showModal()}><Icon name="plus" size={22}/></button>{#if user}<button class="profile-button" aria-label="Your account" aria-expanded={accountOpen} onclick={() => accountOpen = !accountOpen}>{@render avatarImage()}<span>{user.name}</span><svg width="12" height="12" viewBox="0 0 12 12" fill="none" aria-hidden="true"><path d="m3 4 3 3 3-3" stroke="currentColor" stroke-width="1.5"/></svg></button>{:else}<button class="sign-in" onclick={onsignin} disabled={!network}>Log In</button>{/if}</div>
		{#if accountOpen && user}<div class="account-menu"><strong>{user.name}</strong><span>Roblox account</span><a href={`https://www.roblox.com/users/${user.id}/profile`} target="_blank" rel="noreferrer">View profile <Icon name="arrow" size={16}/></a><a href="/apps">Back to Velora <Icon name="apps" size={16}/></a></div>{/if}
	</header>
	<aside class:mobile-open={sidebarOpen}>
		<div class="sidebar-account">{@render avatarImage('medium')}<div><strong>{user?.name || 'Welcome, player'}</strong><span>{user ? 'Let’s play something.' : 'Your next favorite awaits.'}</span></div></div>
		<nav class="side-nav" aria-label="Main navigation">
			{#each [{label:'Home',icon:'home'},{label:'Discover',icon:'globe'},{label:'Continue',icon:'clock'},{label:'Saved',icon:'bookmark'}] as item}<button class:active={view === item.label && !query} onclick={() => navigate(item.label)}><Icon name={item.icon} size={23}/>{item.label}{#if item.label === 'Saved' && saved.length}<span class="nav-count">{saved.length}</span>{/if}</button>{/each}
		</nav>
		<div class="sidebar-divider"></div>
		<button class="sidebar-link" onclick={() => openDialog.showModal()}><Icon name="plus" size={21}/>Open an experience</button>
		<a class="sidebar-link" href="/os"><Icon name="desktop" size={21}/>Velora desktop <span class="external">↗</span></a>
		<div class="sidebar-bottom"><button class="connection-button" onclick={() => connectionDialog.showModal()}><span class:preparing={connectionState === 'preparing'} class:failed={connectionState === 'error'} class="connection-dot"></span>{connectionState === 'preparing' ? 'Connecting…' : connectionState === 'error' ? 'Connection issue' : 'Connected'}<Icon name="settings" size={16}/></button><p><a href="/os">VELORA</a><span>Experimental web client</span></p></div>
	</aside>
	<main>
		<div class="page-heading"><h1>{title}</h1>{#if view === 'Home' && !query}<span class="greeting">{user ? `Good to see you, ${user.name}.` : 'A world of possibilities.'}</span>{/if}</div>
		{#if !user && !query && view === 'Home'}<div class="welcome-banner"><div class="welcome-icon"><img class="velora-mark" src={veloraMark} alt=""/></div><div><h2>More fun when you’re you.</h2><p>Log in to your Roblox account and jump into an experience.</p></div><button class="sign-in" onclick={onsignin} disabled={!network}>Log In <Icon name="arrow" size={17}/></button></div>{/if}
		{#if error}<div class="notice error-notice" role="alert"><span>{error}</span><button onclick={() => connectionDialog.showModal()}>Connection details</button></div>{/if}
		{#if view === 'Home' && !query && recentGames.length}<section class="continue-section"><div class="section-heading"><h2>Continue</h2><button onclick={() => navigate('Continue')}>See all <Icon name="forward" size={16}/></button></div><div class="game-grid recent-grid">{#each recentGames.slice(0, 6) as game (game.placeId)}{@render gameCard(game)}{/each}</div></section>{/if}
		{#if view === 'Home' || view === 'Discover' || query}<div class="section-heading recommended-heading"><h2>{query ? 'Experiences' : view === 'Discover' ? 'Find your next favorite' : 'Recommended for you'}</h2>{#if !query}<button onclick={() => navigate(view === 'Home' ? 'Discover' : 'Home')}>{view === 'Home' ? 'See all' : 'Back home'} <Icon name="forward" size={16}/></button>{/if}</div><div class="categories" aria-label="Experience categories">{#each categories as label}<button class:chosen={category === label} aria-pressed={category === label} onclick={() => category = label}>{label}</button>{/each}</div>{/if}
		{#if parsePlace(query)}<button class="link-result" onclick={() => openPlace(query)}><span class="link-result-icon"><Icon name="games" size={26}/></span><span><strong>Open this experience</strong><small>Place ID {parsePlace(query)}</small></span><Icon name="arrow" size={23}/></button>{/if}
		{#if view === 'Continue' && !query}<p class="collection-description">Experiences you opened on this browser.</p><div class="game-grid">{#each recentGames as game (game.placeId)}{@render gameCard(game)}{/each}</div>{#if !recentGames.length}<div class="empty-state"><Icon name="clock" size={36}/><h2>Your next adventure starts here</h2><p>Experiences you play will appear here so you can jump back in.</p><button onclick={() => navigate('Discover')}>Discover experiences</button></div>{/if}
		{:else}<div class="game-grid">{#each filtered as game (game.placeId)}{@render gameCard(game)}{/each}</div>{#if !filtered.length && !parsePlace(query)}<div class="empty-state"><Icon name={view === 'Saved' ? 'bookmark' : 'search'} size={36}/><h2>{view === 'Saved' ? 'Make room for your favorites' : 'No experiences found'}</h2><p>{view === 'Saved' ? 'Save a game with its bookmark to find it here.' : 'Try another name, or paste a Roblox game link to open it.'}</p><button onclick={() => navigate('Discover')}>Explore experiences</button></div>{/if}{/if}
		{#if !query && view === 'Home'}<div class="any-game"><span class="any-game-icon"><Icon name="games" size={25}/></span><div><strong>Already have a game in mind?</strong><p>Paste its Roblox link and make yourself at home.</p></div><button onclick={() => openDialog.showModal()}>Open game <Icon name="arrow" size={17}/></button></div>{/if}
		{#if catalogError}<p class="catalog-notice">Live game info is unavailable. You can still open an experience. <button onclick={() => loadCatalog(network)} disabled={!network}>Retry</button></p>{/if}
		<footer><span>Powered by Velora. Independent of Roblox Corporation.</span><button onclick={() => connectionDialog.showModal()}>Connection details</button></footer>
	</main>
</div>

<dialog class="experience-dialog" bind:this={detailDialog} onclose={() => { selected = null; lookupError = ''; }}>
	{#if selected}<div class="experience-modal"><button class="modal-close icon-button" aria-label="Close experience" onclick={() => detailDialog.close()}><Icon name="close" size={22}/></button><div class="detail-art">{#if selected.image}<img src={selected.image} crossorigin={selected.image.startsWith('https:') ? 'anonymous' : undefined} alt=""/>{:else}<Icon name="games" size={70}/>{/if}</div><div class="detail-copy"><span class="detail-category">{selected.genre || 'Roblox experience'}</span><h2>{selected.name}</h2>{#if selected.creator}<p>By <strong>{selected.creator}</strong></p>{/if}<div class="detail-stats">{#if selected.rating != null}<span><strong>{selected.rating}%</strong>Liked</span>{/if}{#if typeof selected.playing === 'number'}<span><strong>{compactNumber(selected.playing)}</strong>Active</span>{/if}{#if typeof selected.visits === 'number'}<span><strong>{compactNumber(selected.visits)}</strong>Visits</span>{/if}</div>{#if resolving}<p class="detail-notice" role="status">Looking up experience…</p>{/if}{#if lookupError}<p class="detail-notice" role="alert">{lookupError}</p>{/if}<div class="detail-buttons"><button class="play-button" onclick={launchSelected} disabled={!network || resolving || !!lookupError}><svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="m7 4 14 8-14 8Z"/></svg>{user ? 'Play' : 'Log in to play'}</button><button class="detail-save" aria-label={saved.includes(selected.placeId) ? 'Unsave experience' : 'Save experience'} aria-pressed={saved.includes(selected.placeId)} onclick={() => toggleSave(selected)}><Icon name="bookmark" size={21}/></button></div><small class="compatibility-note">Experimental web play. Some experiences may not work yet.</small></div></div>{/if}
</dialog>
<dialog class="small-dialog" bind:this={openDialog}><form onsubmit={event => { event.preventDefault(); void openPlace(customPlace); }}><div class="dialog-heading"><h2>Open an experience</h2><button type="button" class="icon-button" aria-label="Close game link dialog" onclick={() => openDialog.close()}><Icon name="close" size={21}/></button></div><p>Enter a Roblox game link or a place ID.</p><label for="game-link">Game link or place ID</label><input id="game-link" bind:value={customPlace} placeholder="https://www.roblox.com/games/…" autocomplete="off"/>{#if customError}<p class="detail-notice" role="alert">{customError}</p>{/if}<button class="sign-in open-submit">Find experience <Icon name="arrow" size={17}/></button></form></dialog>
<dialog class="small-dialog" bind:this={connectionDialog}><div class="dialog-heading"><h2>Connection details</h2><button class="icon-button" aria-label="Close connection details" onclick={() => connectionDialog.close()}><Icon name="close" size={21}/></button></div><p role="status">{status}</p>{#each issues as entry}<p class="diagnostic">{entry.time} · {entry.text}</p>{/each}</dialog>

